    {w : Finset (Grid (snapGrid j p M))} {B : Bool}
    (hQ : supported w u.V)
    (hB : biases P p A (snap_le _ _) w B u.v (beta u.ix)) :
    beta u.ix /2 ≤ u.chances P A
